function prefixSum(nums: number[]): number[] {
  // Edge case: if the input array is null, undefined, or empty
  // return an empty array to avoid runtime errors
  if (!nums || nums.length === 0) {
    return [];
  }

  // Create a prefix array of the same length as nums
  // Initialize all values with 0
  const prefix: number[] = new Array(nums.length).fill(0);

  // The first prefix sum is the first element itself
  prefix[0] = nums[0];

  // Build the prefix sum array
  // Each index stores the sum of all elements before it plus the current one
  for (let i = 1; i < nums.length; i++) {
    prefix[i] = prefix[i - 1] + nums[i];
  }

  // Return the computed prefix sum array
  return prefix;
}

