function dutchNationalFlag(nums: number[]): void {
  let low = 0; // Index for 0
  let mid = 0; // Index for 1
  let high = nums.length - 1; // Index for 2

  // Iterate until mid crosses high
  while (mid <= high) {
    if (nums[mid] === 0) {
      // If the element is 0, swap it with the element at low and increment both low and mid
      [nums[low], nums[mid]] = [nums[mid], nums[low]];
      low++;
      mid++;
    } else if (nums[mid] === 1) {
      // If the element is 1, leave it as is and increment mid
      mid++;
    } else {
      // If the element is 2, swap it with the element at high and decrement high
      [nums[mid], nums[high]] = [nums[high], nums[mid]];
      high--;
      // Note: We do not increment mid here because the swapped element at mid needs to be processed in the next iteration
    }
  }
}

