function largestRectangleArea(heights: number[]): number {
    // This will store the maximum rectangle area found so far
    let maxArea = 0;

    // Stack will store indices of bars
    // Important: We store indices, NOT heights
    // So that we can calculate width later
    const stack: number[] = [];

    // We run loop till <= heights.length
    // Why <= ?
    // Because we add one extra iteration (i === heights.length)
    // to flush out remaining bars from stack
    for (let i = 0; i <= heights.length; i++) {

        // While:
        // 1) Stack is not empty
        // 2) AND (we reached end OR current height is smaller than stack top height)
        //
        // This means:
        // Current bar is breaking the increasing height pattern
        // So we must calculate area for bars taller than current
        while (
            stack.length > 0 &&
            (i === heights.length || heights[stack[stack.length - 1]] >= heights[i])
        ) {
            // Get index of the bar forming rectangle height
            const top = stack.pop()!;

            // Calculate width:
            //
            // If stack becomes empty:
            //   It means this bar was smallest so far,
            //   so it spans from index 0 to i-1
            //
            // Otherwise:
            //   Width = distance between current index
            //   and new stack top minus 1
            const width =
                stack.length === 0
                    ? i
                    : i - stack[stack.length - 1] - 1;

            // Area = height * width
            const area = heights[top] * width;

            // Update maximum area
            maxArea = Math.max(maxArea, area);
        }

        // Push current index into stack
        // Stack maintains increasing height order
        stack.push(i);
    }

    return maxArea;
}

