function rotate(nums: number[], k: number): void {

    // If k is larger than array length,
    // rotating n times brings array back to original position.
    // So we take modulo to avoid unnecessary rotations.
    k = k % nums.length;

    // -----------------------------
    // STEP 1: Reverse entire array
    // -----------------------------
    // Example:
    // [1,2,3,4,5,6,7] → [7,6,5,4,3,2,1]

    let l = 0;
    let r = nums.length - 1;

    while (l < r) {
        // Swap left and right elements
        [nums[l], nums[r]] = [nums[r], nums[l]];
        l++;
        r--;
    }

    // ----------------------------------
    // STEP 2: Reverse first k elements
    // ----------------------------------
    // If k = 3
    // [7,6,5,4,3,2,1]
    // → reverse first 3
    // → [5,6,7,4,3,2,1]

    l = 0;
    r = k - 1;

    while (l < r) {
        [nums[l], nums[r]] = [nums[r], nums[l]];
        l++;
        r--;
    }

    // ----------------------------------
    // STEP 3: Reverse remaining elements
    // ----------------------------------
    // Reverse from k to end
    // [5,6,7,4,3,2,1]
    // → [5,6,7,1,2,3,4]

    l = k;
    r = nums.length - 1;

    while (l < r) {
        [nums[l], nums[r]] = [nums[r], nums[l]];
        l++;
        r--;
    }
}

